<script setup lang="ts">
import { ui } from "../ui"
import DateTime from '../components/DateTime.vue'
import {computed,ref,watch,onMounted,onUnmounted} from 'vue'
import {onBeforeRouteLeave} from 'vue-router'
import {EnvelopeIcon,CodeBracketIcon,ChatBubbleLeftRightIcon,SignalIcon} from '@heroicons/vue/24/outline'
import PageHeading from '../components/PageHeading.vue'
import CheckboxDropdown from '../components/CheckboxDropdown.vue'
import {api,bootstrap,notify} from '../composables/api'
import {useCollaborationAction} from '../composables/collaboration'
import type {IntegrationConfiguration,IntegrationConnection,TestDeliveryOperation} from '../types'
type Provider='slack'|'webhook'|'github'
const data=ref<IntegrationConfiguration|null>(null),loading=ref(true),error=ref(''),saving=ref(false),selected=ref<Provider|null>(null),editing=ref<string|null>(null),replacing=ref<IntegrationConnection|null>(null),form=ref({name:'',enabled:false,endpoint:'',owner:'',repo:'',credential:'',credential_reference:'',events:[] as string[],automatic:false,environments:[] as string[],labels:[] as string[]}),baseline=ref(''),version=ref(0),editor=ref(false)
const once=ref<{secret:string;key_id:string;state:string}|null>(null),testConfirmation=ref<{id:string;key?:string}|null>(null),operation=ref<TestDeliveryOperation|null>(null),polling=ref(false),tokenEditor=ref(false)
const perform=useCollaborationAction(),current=computed(()=>data.value?.connections.find(c=>c.id===editing.value)),dirty=computed(()=>editor.value&&baseline.value!==JSON.stringify(form.value)),canManage=computed(()=>bootstrap.value?.capabilities.manage)
type Repository={owner:string;repo:string;full_name:string;private:boolean}
const repositories=ref<Repository[]>([]),repositorySelection=ref(''),repositoryPage=ref<number|null>(null),repositoryLoading=ref(false),repositoryLoaded=ref(false),repositoryError=ref(''),manualRepository=ref(false)
let repositoryRequest=0
function resetRepositories(){repositoryRequest++;repositories.value=[];repositorySelection.value='';repositoryPage.value=null;repositoryLoaded.value=false;repositoryLoading.value=false;repositoryError.value='';if(!editing.value){form.value.owner='';form.value.repo=''}}
watch(()=>[form.value.credential,form.value.credential_reference],resetRepositories)
watch(manualRepository,value=>{if(!value){const repo=repositories.value.find(r=>r.full_name===repositorySelection.value);form.value.owner=repo?.owner??'';form.value.repo=repo?.repo??''}})
watch(repositorySelection,value=>{const repo=repositories.value.find(r=>r.full_name===value);if(repo){form.value.owner=repo.owner;form.value.repo=repo.repo;if(!form.value.name)form.value.name=repo.full_name}})
async function discoverRepositories(more=false){
 const request=++repositoryRequest;repositoryLoading.value=true;repositoryError.value=''
 try{const result=await api<{repositories:Repository[];next_page:number|null}>('/integrations/github/repositories','POST',{credential:form.value.credential,credential_reference:form.value.credential_reference,page:more?repositoryPage.value:1});if(request!==repositoryRequest||disposed)return;repositories.value=more?[...repositories.value,...result.repositories.filter(r=>!repositories.value.some(old=>old.full_name===r.full_name))]:result.repositories;repositoryPage.value=result.next_page;repositoryLoaded.value=true}
 catch(e){if(request===repositoryRequest)repositoryError.value=e instanceof Error?e.message:'Could not load repositories. Try again.'}
 finally{if(request===repositoryRequest)repositoryLoading.value=false}
}
const providers=[{id:'email',name:'Email',description:'Host mailer · one canonical recipient per destination',icon:EnvelopeIcon},{id:'github',name:'GitHub Issues',description:'Create or link a ticket in a configured repository',icon:CodeBracketIcon},{id:'slack',name:'Slack',description:'Incoming webhooks · channel label supplied by your administrator',icon:ChatBubbleLeftRightIcon},{id:'webhook',name:'Webhooks',description:'Signed events for your tools · exact-body verification',icon:SignalIcon}]
let timer:ReturnType<typeof setTimeout>|undefined,disposed=false,checks=0
function leave(){return (!dirty.value&&!once.value)||window.confirm(once.value?'Copy this signing key before leaving. It cannot be shown again. Continue?':'Discard your unsaved integration draft?')}
onBeforeRouteLeave(leave)
const unload=(e:BeforeUnloadEvent)=>{if(dirty.value||once.value){e.preventDefault();e.returnValue=''}}
onMounted(()=>{load();window.addEventListener('beforeunload',unload)});onUnmounted(()=>{disposed=true;clearTimeout(timer);window.removeEventListener('beforeunload',unload)})
async function load(){loading.value=true;try{data.value=await api('/integrations');error.value=''}catch(e){error.value=e instanceof Error?e.message:'Integrations unavailable.'}finally{loading.value=false}}
function connections(p:string){return data.value?.connections.filter(c=>c.provider===p)??[]}
function readiness(p:string){const list=connections(p);if(!list.length)return 'Not configured';if(list.some(c=>c.state==='unreadable'||['failed','retrying'].includes(c.last_test_outcome??'')))return 'Needs attention';return list.some(c=>c.enabled&&!c.disconnected)?'Configured':'Disabled'}
function choose(p:Provider,c?:IntegrationConnection,replace=false){if(!leave())return;once.value=null;selected.value=p;editor.value=!!c||connections(p).length===0;editing.value=c&&!replace?c.id:null;replacing.value=replace&&c?c:null;version.value=c?.version??0;tokenEditor.value=false;manualRepository.value=false;resetRepositories();form.value={name:c?.name??'',enabled:c?.enabled??false,endpoint:'',owner:replace?'':c?.target.owner??'',repo:replace?'':c?.target.repo??'',credential:'',credential_reference:'',events:c?.options.events??Object.keys(data.value?.events??{}),automatic:c?.options.automatic??false,environments:c?.options.environments??[],labels:c?.options.labels??[]};baseline.value=JSON.stringify(form.value);error.value=''}
function add(){if(!selected.value||!leave())return;const p=selected.value;choose(p);editor.value=true}
async function save(){if(!selected.value)return;if(selected.value==='github'&&form.value.automatic&&!form.value.environments.length){error.value='Select at least one environment for automatic issue creation.';return}saving.value=true;try{let values:Record<string,unknown>;if(editing.value)values={version:version.value,name:form.value.name,enabled:form.value.enabled,...(selected.value==='github'?{automatic:form.value.automatic,environments:form.value.environments,labels:form.value.labels}:selected.value==='webhook'?{events:form.value.events}:{})};else {const {labels:omittedLabels,...newValues}=form.value;values={provider:selected.value,...newValues,...(replacing.value?{replaces:replacing.value.id,replaces_version:replacing.value.version}:{})}};const result=await perform<{id:string;version:number;once?:typeof once.value}>('/integrations'+(editing.value?'/'+editing.value:''),editing.value?'PATCH':'POST',values);form.value.credential='';baseline.value=JSON.stringify(form.value);editor.value=false;await load();const c=data.value?.connections.find(c=>c.id===result.id);if(c){editing.value=c.id;version.value=c.version}once.value=result.once??null;notify('Integration saved. Existing work keeps its original target.')}catch(e){error.value=e instanceof Error?e.message:'Save failed.'}finally{saving.value=false}}
async function action(c:IntegrationConnection,kind:string,values:Record<string,unknown>={}){if(once.value){error.value='Save and acknowledge the one-time signing key before changing credentials.';return}saving.value=true;try{const result=await perform<{once?:typeof once.value;id:string;version:number}>('/integrations/'+c.id+'/'+kind,'POST',{version:c.version,...values});once.value=result.once??null;await load();version.value=result.version??version.value;notify(kind==='key.stage'?'New key staged. Configure the receiver, test it, then activate explicitly.':'Integration updated.')}catch(e){error.value=e instanceof Error?e.message:'Operation failed.'}finally{saving.value=false}}
async function activate(c:IntegrationConnection,key:string){if(window.confirm('Activate this signing key? Configure the receiver first. The previous key has a 24-hour transition.'))await action(c,'key.activate',{key_id:key})}
async function disconnect(c:IntegrationConnection){if(!window.confirm('Disconnect this target? Pending work is cancelled. In-flight requests cannot be recalled.'))return;saving.value=true;try{await perform('/integrations/'+c.id,'DELETE',{version:c.version});editor.value=false;baseline.value=JSON.stringify(form.value);await load()}catch(e){error.value=e instanceof Error?e.message:'Disconnect failed.'}finally{saving.value=false}}
async function test(){if(!testConfirmation.value)return;saving.value=true;try{const v=testConfirmation.value;const result=await perform<{id:string}>('/integrations/'+v.id+'/test','POST',v.key?{signing_key_id:v.key}:{});testConfirmation.value=null;checks=0;operation.value={id:result.id,items:[],queue_asynchronous:true};polling.value=true;await poll()}catch(e){error.value=e instanceof Error?e.message:'Test could not be queued.'}finally{saving.value=false}}
async function poll(){if(!operation.value||disposed)return;try{operation.value=await api('/alerting/tests/'+operation.value.id);checks++;if(operation.value?.items.some(i=>['pending','processing','retrying'].includes(i.status))&&checks<15){polling.value=true;timer=setTimeout(poll,2000)}else{polling.value=false;await load()}}catch(e){polling.value=false;error.value=e instanceof Error?e.message:'Test status unavailable.'}}
async function reloadDraft(){if(!leave())return;once.value=null;editor.value=false;await load();if(current.value)choose(current.value.provider,current.value)}
</script>
<template>
<PageHeading :class="ui('$all', '$PageHeading')" title="Integrations" subtitle="Notification destinations and issue tracking, in one place."><span :class="ui('$all', '$span', 'badge')">Credentials are encrypted and never redisplayed</span></PageHeading>
<p v-if="bootstrap?.features.controlled_integrations" :class="ui('$all', '$p', 'notice neutral')">Controlled preview · no external requests are sent.</p>
<div v-if="error" :class="ui('$all', '$div', 'notice danger')" role="alert"><div :class="ui('$all', '$div')">{{error}}<button :class="ui('$all', '$button', 'button')" @click="reloadDraft">Reload current configuration</button><p :class="ui('$all', '$p', 'help')">Your draft remains here until you choose to replace it.</p></div></div>
<p :class="ui('$all', '$p')" v-if="loading" role="status">Loading integrations…</p>
<div v-if="data" :class="ui('$all', '$div', 'integration-list')"><article v-for="p in providers" :key="p.id" :class="ui('$all', '$article', 'integration-row')"><component :is="p.icon" :class="ui('$all', '$svg', 'integration-icon')"/><div :class="ui('$all', '$div')"><h2 :class="ui('$all', '$h2')">{{p.name}}</h2><p :class="ui('$all', '$p')">{{p.description}}</p></div><span v-if="p.id!=='email'" :class="ui('$all', '$span', 'status-badge', (readiness(p.id)==='Needs attention'?'status-failed':''))" >{{readiness(p.id)}}</span><span v-else :class="ui('$all', '$span', 'badge')">Host managed</span><RouterLink v-if="p.id==='email'" to="/settings/email" :class="ui('$all', '$a', 'button')">Review email</RouterLink><button v-else :class="ui('$all', '$button', 'button')" @click="choose(p.id as Provider)">{{canManage?'Configure':'Review'}}</button></article></div>
<p :class="ui('$all', '$p', 'help spacing')">Connection checks and individual delivery outcomes are tracked separately. A successful GitHub read check cannot prove that every write will succeed.</p>
<section v-if="selected&&data" :class="ui('$all', '$section', 'integration-workspace')">
<div :class="ui('$all', '$div', 'section-heading')"><h2 :class="ui('$all', '$h2')">{{selected==='github'?'GitHub repositories':selected==='slack'?'Slack destinations':'Signed webhook destinations'}}</h2><button v-if="canManage" :class="ui('$all', '$button', 'button')" :disabled="saving" @click="add">Add {{selected==='github'?'repository':'destination'}}</button></div>
<p v-if="!connections(selected).length" :class="ui('$all', '$p', 'help')">No connection configured yet.</p>
<article v-for="c in connections(selected)" :key="c.id" :class="ui('$all', '$article', 'connection-row')"><div :class="ui('$all', '$div', 'section-heading')"><div :class="ui('$all', '$div')"><h3 :class="ui('$all', '$h3')">{{c.name}}</h3><p :class="ui('$all', '$p')">{{c.display}}</p></div><span :class="ui('$all', '$span', 'badge')">{{c.disconnected?'Disconnected':c.enabled?'Enabled':'Disabled'}}</span></div><p v-if="selected==='slack'" :class="ui('$all', '$p', 'help')">This name is an administrator-supplied label, not a verified Slack channel identity.</p><dl :class="ui('$all', '$dl', 'connection-observations')"><div :class="ui('$all', '$div')"><dt :class="ui('$all', '$dt')">Last {{selected==='github'?'read check':'test'}}</dt><dd :class="ui('$all', '$dd')">{{c.last_test_outcome??'Not tested'}} · <DateTime :class="ui('$all', '$DateTime')" :value="c.last_test_at"/></dd></div><div :class="ui('$all', '$div')"><dt :class="ui('$all', '$dt')">Last transport acceptance</dt><dd :class="ui('$all', '$dd')"><DateTime :class="ui('$all', '$DateTime')" :value="c.last_accepted_at"/></dd></div><div :class="ui('$all', '$div')"><dt :class="ui('$all', '$dt')">Failures / Needs review</dt><dd :class="ui('$all', '$dd')">{{c.failed_count}}</dd></div></dl><p v-if="c.state==='unreadable'" :class="ui('$all', '$p', 'notice warning')">An active credential could not be read. Restore host key availability or replace the credential.</p>
<div v-if="canManage" :class="ui('$all', '$div', 'inline-actions')"><button :class="ui('$all', '$button', 'button')" :disabled="saving" @click="choose(c.provider,c)">{{c.disconnected?'Reconnect':'Edit configuration'}}</button><button v-if="!c.disconnected" :class="ui('$all', '$button', 'button')" :disabled="saving||dirty||polling" @click="testConfirmation={id:c.id}">{{selected==='github'?'Check repository access':'Send synthetic test'}}</button><button :class="ui('$all', '$button', 'button')" :disabled="saving" @click="choose(c.provider,c,true)">Replace target</button><button v-if="!c.disconnected" :class="ui('$all', '$button', 'text-link danger-link')" :disabled="saving" @click="disconnect(c)">Disconnect</button></div>
<template v-if="c.provider==='webhook'&&canManage"><div :class="ui('$all', '$div', 'signing-keys')"><h4 :class="ui('$all', '$h4')">Signing keys</h4><p :class="ui('$all', '$p', 'help')">Stage a key, configure your receiver, send a labeled test, then activate. Keep the previous key for the displayed transition deadline.</p><ul :class="ui('$all', '$ul')"><li :class="ui('$all', '$li')" v-for="k in c.keys?.filter(k=>k.purpose==='webhook_signing')" :key="k.id"><span :class="ui('$all', '$span', 'code')">{{k.id}}</span> · {{k.state}}<span :class="ui('$all', '$span')" v-if="k.retire_after"> · transition ends <DateTime :class="ui('$all', '$DateTime')" :value="k.retire_after"/></span><div v-if="k.state==='staged'" :class="ui('$all', '$div', 'inline-actions')"><button :class="ui('$all', '$button', 'button')" :disabled="saving||dirty||polling" @click="testConfirmation={id:c.id,key:k.id}">Test staged key</button><button :class="ui('$all', '$button', 'button')" :disabled="saving||dirty||!!once" @click="activate(c,k.id)">Activate key</button></div></li></ul><button :class="ui('$all', '$button', 'button')" :disabled="saving||dirty||!!once" @click="action(c,'key.stage')">Stage signing key</button></div></template>
<RouterLink :to="{path:'/alerts/history',query:{channel:c.provider}}" :class="ui('$all', '$a', 'text-link')">Inspect {{c.provider}} delivery history</RouterLink></article>
<form v-if="editor&&canManage" :class="ui('$all', '$form', 'panel integration-editor')" @submit.prevent="save"><h3 :class="ui('$all', '$h3')">{{editing?'Edit configuration':replacing?'Replace immutable target':'New connection'}}</h3><p :class="ui('$all', '$p', 'help')">Changing the target creates a separate destination and disconnects the old one. Pending work is never redirected.</p><label v-if="selected!=='github'||editing||manualRepository||repositorySelection" :class="ui('$all', '$label', 'field')">Display name<input :class="ui('$all', '$input')" v-model="form.name" required maxlength="120"></label>
<template v-if="!editing">
<template v-if="selected==='github'">
<label :class="ui('$all', '$label', 'field')">Personal access token<input :class="ui('$all', '$input')" v-model="form.credential" type="password" :required="!form.credential_reference" :disabled="!!form.credential_reference" autocomplete="new-password" spellcheck="false"><small :class="ui('$all', '$small')">Use a fine-grained token with access to your repository and Issues: Read and write. <a :class="ui('$all', '$a')" href="https://github.com/settings/personal-access-tokens/new" target="_blank" rel="noopener noreferrer">Create a token on GitHub</a>.</small></label>
</template>
<label v-else :class="ui('$all', '$label', 'field')">{{selected==='slack'?'Slack incoming webhook URL':'HTTPS endpoint'}}<input :class="ui('$all', '$input')" v-model="form.endpoint" type="password" :required="!form.credential_reference" autocomplete="new-password" spellcheck="false"><small :class="ui('$all', '$small')">The endpoint is stored encrypted. It will not be redisplayed.</small></label>
<label v-if="data.credential_references.length&&selected!=='webhook'" :class="ui('$all', '$label', 'field')">Or use a deployment credential reference<select :class="ui('$all', '$select')" v-model="form.credential_reference"><option :class="ui('$all', '$option')" value="">Use the entered credential</option><option :class="ui('$all', '$option')" v-for="r in data.credential_references" :key="r">{{r}}</option></select></label>
<template v-if="selected==='github'">
<div :class="ui('$all', '$div', 'inline-actions')"><button type="button" :class="ui('$all', '$button', 'button')" :disabled="repositoryLoading||(!form.credential&&!form.credential_reference)" @click="discoverRepositories()">{{repositoryLoading?'Loading repositories…':'Load repositories'}}</button><button type="button" :class="ui('$all', '$button', 'text-link')" @click="manualRepository=!manualRepository">{{manualRepository?'Choose from repository list':'Enter repository manually'}}</button></div>
<p v-if="repositoryError" :class="ui('$all', '$p', 'notice danger')" role="alert">{{repositoryError}}</p>
<template v-if="!manualRepository">
<label :class="ui('$all', '$label', 'field')">Repository<select :class="ui('$all', '$select')" v-model="repositorySelection" required :disabled="repositoryLoading||!repositories.length"><option :class="ui('$all', '$option')" value="">{{repositoryLoaded?'Select a repository':'Load repositories using your token first'}}</option><option :class="ui('$all', '$option')" v-for="repo in repositories" :key="repo.full_name" :value="repo.full_name">{{repo.full_name}}{{repo.private?' · Private':''}}</option></select><small :class="ui('$all', '$small')">Repositories visible to this token with Issues enabled. A repository listing does not confirm Issues write permission.</small></label>
<p v-if="repositoryLoaded&&!repositories.length" role="status" :class="ui('$all', '$p', 'help')">No eligible repositories on this page. Check the token's selected repositories and enable Issues, load more results, or enter a repository manually.</p>
<button v-if="repositoryPage" type="button" :class="ui('$all', '$button', 'button')" :disabled="repositoryLoading" @click="discoverRepositories(true)">Load more repositories</button>
</template>
<div v-else :class="ui('$all', '$div', 'integration-repository-fields')"><label :class="ui('$all', '$label', 'field')">Repository owner<input :class="ui('$all', '$input')" v-model="form.owner" required autocomplete="off"></label><label :class="ui('$all', '$label', 'field')">Repository name<input :class="ui('$all', '$input')" v-model="form.repo" required autocomplete="off"></label></div>
</template>
</template>
<template v-if="selected==='github'"><label :class="ui('$all', '$label', 'checkbox-row')"><input :class="ui('$all', '$input')" v-model="form.automatic" type="checkbox">Create a GitHub issue automatically for new live errors</label><p :class="ui('$all', '$p', 'help')">Opt-in only. Regressions retain their association; reconciliation and test captures never create tickets.</p><CheckboxDropdown :class="ui('$all', '$CheckboxDropdown')" v-if="form.automatic" v-model="form.environments" label="Explicit automatic-creation environments" :options="data.allowed_environments" :disabled="saving"/><fieldset :class="ui('$all', '$fieldset')" v-if="editing&&current?.options.known_labels?.length"><legend :class="ui('$all', '$legend')">Existing repository labels</legend><label v-for="label in current.options.known_labels" :key="label" :class="ui('$all', '$label', 'checkbox-row')"><input :class="ui('$all', '$input')" v-model="form.labels" type="checkbox" :value="label">{{label}}</label></fieldset><p v-else :class="ui('$all', '$p', 'help')">Run a read-only repository check after saving to load existing labels.</p></template>
<fieldset :class="ui('$all', '$fieldset')" v-if="selected==='webhook'"><legend :class="ui('$all', '$legend')">Allowed webhook events</legend><label v-for="(label,event) in data.events" :key="event" :class="ui('$all', '$label', 'checkbox-row')"><input :class="ui('$all', '$input')" v-model="form.events" type="checkbox" :value="event">{{label}}</label></fieldset><label :class="ui('$all', '$label', 'checkbox-row')"><input :class="ui('$all', '$input')" v-model="form.enabled" type="checkbox">Enable this connection</label><div :class="ui('$all', '$div', 'inline-actions spacing')"><button :class="ui('$all', '$button', 'button primary')" :disabled="saving||(selected==='github'&&!editing&&(!form.owner||!form.repo))">{{saving?'Saving…':'Save connection'}}</button><button type="button" :class="ui('$all', '$button', 'button')" :disabled="saving" @click="leave()&&(editor=false)">Cancel draft</button><span v-if="dirty" :class="ui('$all', '$span', 'unsaved')">Unsaved changes</span></div>
<template v-if="editing&&selected==='github'&&current"><hr :class="ui('$all', '$hr')"><h4 :class="ui('$all', '$h4')">Replace repository token</h4><label :class="ui('$all', '$label', 'field')">New token<input :class="ui('$all', '$input')" v-model="form.credential" type="password" autocomplete="new-password"></label><button type="button" :class="ui('$all', '$button', 'button')" :disabled="saving||!form.credential||!!once" @click="action(current,'secret.replace',{credential:form.credential});form.credential=''">Replace token</button><p :class="ui('$all', '$p', 'help')">The repository stays fixed; workers load the current credential at execution.</p></template></form>
</section>
<section v-if="once" :class="ui('$all', '$section', 'notice warning one-time-secret')" role="status"><div :class="ui('$all', '$div')"><h3 :class="ui('$all', '$h3')">Copy this {{once.state}} signing key now</h3><p :class="ui('$all', '$p')">It cannot be retrieved again. Configure the receiver before sending or activating it.</p><label :class="ui('$all', '$label', 'field')">Key identifier<input :class="ui('$all', '$input')" :value="once.key_id" readonly></label><label :class="ui('$all', '$label', 'field')">Shared secret<input :class="ui('$all', '$input')" :value="once.secret" readonly autocomplete="off" spellcheck="false"></label><button :class="ui('$all', '$button', 'button')" @click="once=null">I saved this key</button></div></section>
<section v-if="testConfirmation" :class="ui('$all', '$section', 'notice warning')" role="alert"><div :class="ui('$all', '$div')"><h3 :class="ui('$all', '$h3')">Confirm integration test</h3><p :class="ui('$all', '$p')" v-if="selected==='github'">Read repository metadata and existing labels. This does not create a GitHub issue or prove write access.</p><p :class="ui('$all', '$p')" v-else>Queue one labeled synthetic message to the configured destination{{testConfirmation.key?' using the staged key without activating it':''}}. {{bootstrap?.features.controlled_integrations?'This uses the controlled preview transport.':'This contacts the real configured endpoint.'}}</p><div :class="ui('$all', '$div', 'inline-actions')"><button :class="ui('$all', '$button', 'button primary')" :disabled="saving" @click="test">Confirm queued test</button><button :class="ui('$all', '$button', 'button')" :disabled="saving" @click="testConfirmation=null">Cancel test</button></div></div></section>
<section v-if="operation" :class="ui('$all', '$section', 'panel integration-test-result')" role="status"><h3 :class="ui('$all', '$h3')">{{polling?'Checking queued operation…':'Test operation'}}</h3><ul :class="ui('$all', '$ul')"><li :class="ui('$all', '$li')" v-for="item in operation.items" :key="item.id"><RouterLink :class="ui('$all', '$a')" :to="'/alerts/history/'+item.id">{{item.destination_name}} · {{item.status}}</RouterLink><span :class="ui('$all', '$span')" v-if="item.reason"> · {{item.reason}}</span></li></ul><p v-if="!operation.queue_asynchronous" :class="ui('$all', '$p', 'help')">No supported asynchronous queue is configured. Intent remains durable.</p><p :class="ui('$all', '$p', 'help')">Acceptance is an observation of this attempt, not proof of future delivery or a currently running worker.</p><button :class="ui('$all', '$button', 'button')" :disabled="polling" @click="checks=0;poll()">Refresh operation</button></section>
</template>
